// Parse the prompt generator response
const response = $input.first().json;
const inputData = $('Workflow Input').first().json;

let content = response.choices[0].message.content;

// Handle markdown code blocks
if (content.startsWith('```')) {
  content = content.replace(/```json\n?/g, '').replace(/```\n?/g, '');
}

try {
  const parsed = JSON.parse(content.trim());

  return {
    json: {
      ...parsed,
      index: inputData.index,
      total: inputData.total,
      original_opportunity: inputData.opportunity
    }
  };
} catch (error) {
  // If parsing fails, create a fallback prompt
  const opp = inputData.opportunity;
  return {
    json: {
      opportunity_id: opp.id,
      prompt: `Professional ${opp.visual_type} visualization showing ${opp.context}. ${opp.suggested_style} style, clean design, suitable for business blog. Data points: ${opp.data_points.join(', ')}. High quality, publication ready.`,
      negative_prompt: "blurry, low quality, amateur, cluttered, hard to read, watermark",
      aspect_ratio: "16:9",
      resolution: "2K",
      visual_type: opp.visual_type,
      filename_suggestion: `visual-${opp.id}-${opp.visual_type.toLowerCase().replace(/\s+/g, '-')}`,
      index: inputData.index,
      total: inputData.total,
      original_opportunity: opp,
      parse_error: error.message
    }
  };
}

// Store task info and prepare for status checking
const taskResponse = $input.first().json;
const promptData = $('Parse Prompt Response').first().json;

return {
  json: {
    taskId: taskResponse.taskId || taskResponse.data?.taskId || taskResponse.id,
    status: 'queued',
    checkCount: 0,
    maxChecks: 30,
    promptData: promptData,
    opportunity_id: promptData.opportunity_id,
    filename: promptData.filename_suggestion
  }
};

// Process status response
const statusResponse = $input.first().json;

// Get previous task data
let previousData;
try {
  previousData = $('Store Task Info').first().json;
} catch (e) {
  try {
    previousData = $('Prepare Next Check').first().json;
  } catch (e2) {
    previousData = { checkCount: 0, maxChecks: 30 };
  }
}

// Extract status and image URL
const status = statusResponse.status || statusResponse.data?.status || 'unknown';
const imageUrl = statusResponse.output?.image_url || 
                 statusResponse.data?.output?.image_url ||
                 statusResponse.result?.url ||
                 statusResponse.data?.result?.url ||
                 statusResponse.output?.url ||
                 statusResponse.data?.output?.url ||
                 statusResponse.url ||
                 null;

const checkCount = (previousData.checkCount || 0) + 1;
const maxChecks = previousData.maxChecks || 30;

const isComplete = ['successful', 'completed', 'success', 'done'].includes(status.toLowerCase());
const isFailed = ['failed', 'error', 'cancelled'].includes(status.toLowerCase()) || checkCount >= maxChecks;
const shouldRetry = !isComplete && !isFailed;

return {
  json: {
    taskId: previousData.taskId,
    status: status,
    imageUrl: imageUrl,
    checkCount: checkCount,
    maxChecks: maxChecks,
    isComplete: isComplete,
    isFailed: isFailed,
    shouldRetry: shouldRetry,
    promptData: previousData.promptData,
    opportunity_id: previousData.opportunity_id,
    filename: previousData.filename
  }
};

// Prepare success result to return to main workflow
const driveResponse = $input.first().json;
const statusData = $('Process Status').first().json;

return {
  json: {
    success: true,
    opportunity_id: statusData.opportunity_id,
    visual_type: statusData.promptData?.visual_type,
    filename: statusData.filename,
    drive_file_id: driveResponse.id,
    drive_url: driveResponse.webViewLink || driveResponse.webContentLink,
    original_quote: statusData.promptData?.original_opportunity?.quote,
    checks_required: statusData.checkCount
  }
};

// Prepare data for next status check
const data = $input.first().json;

return {
  json: {
    taskId: data.taskId,
    checkCount: data.checkCount,
    maxChecks: data.maxChecks,
    promptData: data.promptData,
    opportunity_id: data.opportunity_id,
    filename: data.filename
  }
};

// Process retry status response
const statusResponse = $input.first().json;
const previousData = $('Prepare Next Check').first().json;

// Extract status and image URL
const status = statusResponse.status || statusResponse.data?.status || 'unknown';
const imageUrl = statusResponse.output?.image_url || 
                 statusResponse.data?.output?.image_url ||
                 statusResponse.result?.url ||
                 statusResponse.data?.result?.url ||
                 statusResponse.output?.url ||
                 statusResponse.data?.output?.url ||
                 statusResponse.url ||
                 null;

const checkCount = (previousData.checkCount || 0) + 1;
const maxChecks = previousData.maxChecks || 30;

const isComplete = ['successful', 'completed', 'success', 'done'].includes(status.toLowerCase());
const isFailed = ['failed', 'error', 'cancelled'].includes(status.toLowerCase()) || checkCount >= maxChecks;
const shouldRetry = !isComplete && !isFailed;

return {
  json: {
    taskId: previousData.taskId,
    status: status,
    imageUrl: imageUrl,
    checkCount: checkCount,
    maxChecks: maxChecks,
    isComplete: isComplete,
    isFailed: isFailed,
    shouldRetry: shouldRetry,
    promptData: previousData.promptData,
    opportunity_id: previousData.opportunity_id,
    filename: previousData.filename
  }
};

// Prepare success result from retry
const driveResponse = $input.first().json;
const statusData = $('Process Retry Status').first().json;

return {
  json: {
    success: true,
    opportunity_id: statusData.opportunity_id,
    visual_type: statusData.promptData?.visual_type,
    filename: statusData.filename,
    drive_file_id: driveResponse.id,
    drive_url: driveResponse.webViewLink || driveResponse.webContentLink,
    original_quote: statusData.promptData?.original_opportunity?.quote,
    checks_required: statusData.checkCount
  }
};

// Prepare for next loop iteration
const data = $input.first().json;

return {
  json: {
    taskId: data.taskId,
    checkCount: data.checkCount,
    maxChecks: data.maxChecks,
    promptData: data.promptData,
    opportunity_id: data.opportunity_id,
    filename: data.filename
  }
};

// Handle failure - return error result to main workflow
const statusData = $input.first().json;

return {
  json: {
    success: false,
    opportunity_id: statusData.opportunity_id,
    visual_type: statusData.promptData?.visual_type,
    filename: statusData.filename,
    error: statusData.checkCount >= statusData.maxChecks ? 
      `Timeout: max retries exceeded (${statusData.checkCount} checks)` : 
      `Generation failed with status: ${statusData.status}`,
    checkCount: statusData.checkCount,
    lastStatus: statusData.status,
    original_quote: statusData.promptData?.original_opportunity?.quote
  }
};

// Handle final failure after loop exhausted
const statusData = $input.first().json;

return {
  json: {
    success: false,
    opportunity_id: statusData.opportunity_id,
    visual_type: statusData.promptData?.visual_type,
    filename: statusData.filename,
    error: statusData.checkCount >= statusData.maxChecks ? 
      `Timeout: max retries exceeded (${statusData.checkCount} checks)` : 
      `Generation failed with status: ${statusData.status}`,
    checkCount: statusData.checkCount,
    lastStatus: statusData.status,
    original_quote: statusData.promptData?.original_opportunity?.quote
  }
};
